	if userID == 0 {
		return nil, repository.ErrInvalidInput
	}
	var account model.BillingAccount
	err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).Where("user_id = ?", userID).First(&account).Error
	if err == nil {
		return &account, nil
	}
